code.java:
class Solution {
    public boolean xorGame(int[] nums){
        int xor=0;
        for(int value:nums)xor^=value;
        return xor==0||nums.length%2==0;
    }
}

code.kotlin:
class Solution {
    fun xorGame(nums:IntArray):Boolean{
        var xor=0;
        for(value in nums)xor=xor xor value;
        return xor==0||nums.size%2==0
    }
}

code.cpp:
class Solution {
    public: bool xorGame(vector<int>& nums){
        int value=0;
        for(int number:nums)value^=number;
        return value==0||nums.size()%2==0;
    }
};
